function(container, apiUrl, tables) {
  // 業務ロジックモジュールのインポート
  const { 
    collectSalesData, 
    classifySalesDataByProduct, 
    classifySalesDataByStore, 
    filterValidProductData,
    collectWeatherData,
    collectEventData,
    collectSeasonalData,
    analyzeCorrelationSalesWeather,
    analyzeCorrelationSalesEvent,
    analyzeCorrelationSalesSeason,
    compareWithHistoricalData,
    findAlternativeComparisonData,
    validateComparisonPeriod
  } = window.aivicLogic || {};

  // テーブルインデックス定義
  const STORES_TABLE = 1; // 店舗マスタ
  const PRODUCTS_TABLE = 2; // 商品マスタ
  const FORECAST_TABLE = 9; // 需要予測結果
  const ORDERS_TABLE = 10; // 発注データ

  let currentForecastData = [];
  let storesData = [];
  let productsData = [];

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  const orderDateInput = container.querySelector('#order-date');
  if (orderDateInput) {
    orderDateInput.value = today;
  }

  // 納期予定日を3日後に設定
  const deliveryDate = new Date();
  deliveryDate.setDate(deliveryDate.getDate() + 3);
  const deliveryDateInput = container.querySelector('#delivery-date');
  if (deliveryDateInput) {
    deliveryDateInput.value = deliveryDate.toISOString().split('T')[0];
  }

  // エラー表示関数
  function showError(message) {
    if (window.aivicNotify && window.aivicNotify.error) {
      window.aivicNotify.error(message);
    } else {
      const errorDiv = container.querySelector('#error-message');
      if (errorDiv) {
        errorDiv.textContent = message;
        errorDiv.classList.remove('hidden');
        setTimeout(() => errorDiv.classList.add('hidden'), 5000);
      }
    }
  }

  // 成功メッセージ表示関数
  function showSuccess(message) {
    if (window.aivicNotify && window.aivicNotify.success) {
      window.aivicNotify.success(message);
    }
  }

  // 合計金額計算・表示
  function updateTotalAmount() {
    let total = 0;
    container.querySelectorAll('.order-quantity-input').forEach(input => {
      const quantity = parseInt(input.value) || 0;
      const price = parseInt(input.dataset.price) || 0;
      total += quantity * price;
    });
    const totalAmountElement = container.querySelector('#total-amount');
    if (totalAmountElement) {
      totalAmountElement.textContent = '¥' + total.toLocaleString();
    }
  }

  // 発注数量入力フィールドのイベントハンドラ
  function setupQuantityInput(input) {
    input.addEventListener('input', function() {
      const quantity = parseInt(this.value) || 0;
      const price = parseInt(this.dataset.price) || 0;
      const amountCell = this.closest('tr').querySelector('.order-amount');
      if (amountCell) {
        amountCell.textContent = '¥' + (quantity * price).toLocaleString();
      }
      updateTotalAmount();
    });

    input.addEventListener('blur', function() {
      // 数値バリデーション
      const value = this.value.trim();
      if (value !== '' && (isNaN(value) || parseInt(value) < 0)) {
        showError('発注数量は0以上の数値を入力してください');
        this.focus();
      }
    });
  }

  // 需要予測結果テーブル描画
  function renderForecastTable(data) {
    const tbody = container.querySelector('#forecast-tbody');
    if (!tbody) return;

    if (!data || data.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; color: var(--text-muted); padding: 40px;">該当するデータがありません</td></tr>';
      updateTotalAmount();
      return;
    }

    tbody.innerHTML = data.map(item => {
      const product = productsData.find(p => p.商品ID === item.商品ID) || {};
      const orderAmount = 0; // 初期値は0

      return `
        <tr data-product-id="${item.商品ID}">
          <td>${product.商品コード || ''}</td>
          <td>${product.商品名 || ''}</td>
          <td>${product.商品カテゴリID || ''}</td>
          <td style="text-align: right;">${item.予測数量 || 0}</td>
          <td style="text-align: right;">${item.推奨発注数量 || 0}</td>
          <td style="text-align: right;">${Math.floor(Math.random() * 100)}</td>
          <td>
            <input type="number" 
                   class="input order-quantity-input" 
                   min="0" 
                   value="${item.推奨発注数量 || 0}"
                   data-price="${product.仕入価格 || 0}">
          </td>
          <td class="order-amount" style="text-align: right;">¥${((item.推奨発注数量 || 0) * (product.仕入価格 || 0)).toLocaleString()}</td>
          <td>${item.予測日 || ''}</td>
        </tr>
      `;
    }).join('');

    // 発注数量入力フィールドにイベントハンドラを設定
    container.querySelectorAll('.order-quantity-input').forEach(setupQuantityInput);
    updateTotalAmount();
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ読み込み
      if (window.aivicApi && window.aivicApi.list) {
        const storesResponse = await window.aivicApi.list(tables[STORES_TABLE]);
        storesData = storesResponse.data || [];

        // 商品データ読み込み
        const productsResponse = await window.aivicApi.list(tables[PRODUCTS_TABLE]);
        productsData = productsResponse.data || [];

        // 店舗選択肢を設定
        const storeSelect = container.querySelector('#store-select');
        if (storeSelect) {
          storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
            storesData.map(store => `<option value="${store.店舗ID}">${store.店舗名}</option>`).join('');
        }
      }
    } catch (error) {
      console.error('初期データ読み込みエラー:', error);
      showError('初期データの読み込みに失敗しました');
    }
  }

  // 需要予測データ検索
  async function searchForecastData() {
    try {
      const storeId = container.querySelector('#store-select')?.value;
      const forecastDate = container.querySelector('#forecast-date')?.value;

      if (!storeId) {
        showError('店舗を選択してください');
        return;
      }

      if (!forecastDate) {
        showError('予測日を入力してください');
        return;
      }

      // 業務ロジックを使用して売上データを収集
      if (collectSalesData && classifySalesDataByProduct) {
        const salesData = await collectSalesData({
          storeId: storeId,
          startDate: forecastDate,
          endDate: forecastDate
        });

        const classifiedData = classifySalesDataByProduct(salesData);
        const validProductData = filterValidProductData ? filterValidProductData(classifiedData) : classifiedData;

        // 需要予測結果を取得
        if (window.aivicApi && window.aivicApi.list) {
          const forecastResponse = await window.aivicApi.list(tables[FORECAST_TABLE], {
            店舗ID: storeId,
            予測日: forecastDate
          });

          currentForecastData = forecastResponse.data || [];
          renderForecastTable(currentForecastData);
        }
      }
    } catch (error) {
      console.error('予測データ検索エラー:', error);
      showError('予測データの検索に失敗しました');
    }
  }

  // 発注実行
  async function executeOrder() {
    try {
      const storeId = container.querySelector('#store-select')?.value;
      const orderDate = container.querySelector('#order-date')?.value;
      const deliveryDate = container.querySelector('#delivery-date')?.value;

      if (!storeId || !orderDate || !deliveryDate) {
        showError('必須項目を入力してください');
        return;
      }

      // 発注データを収集
      const orderItems = [];
      container.querySelectorAll('#forecast-tbody tr[data-product-id]').forEach(row => {
        const productId = row.dataset.productId;
        const quantityInput = row.querySelector('.order-quantity-input');
        const quantity = parseInt(quantityInput?.value) || 0;

        if (quantity > 0) {
          const product = productsData.find(p => p.商品ID === productId);
          orderItems.push({
            商品ID: productId,
            発注数量: quantity,
            仕入価格: product?.仕入価格 || 0,
            発注金額: quantity * (product?.仕入価格 || 0)
          });
        }
      });

      if (orderItems.length === 0) {
        showError('発注する商品がありません');
        return;
      }

      // 発注データを保存
      if (window.aivicApi && window.aivicApi.save) {
        const orderData = {
          店舗ID: storeId,
          発注日: orderDate,
          納期予定日: deliveryDate,
          発注明細: orderItems,
          合計金額: orderItems.reduce((sum, item) => sum + item.発注金額, 0),
          ステータス: '発注済み'
        };

        await window.aivicApi.save(tables[ORDERS_TABLE], orderData);
        showSuccess('発注が正常に実行されました');

        // フォームをリセット
        container.querySelectorAll('.order-quantity-input').forEach(input => {
          input.value = '0';
        });
        updateTotalAmount();
      }
    } catch (error) {
      console.error('発注実行エラー:', error);
      showError('発注の実行に失敗しました');
    }
  }

  // 推奨数量を一括設定
  function setRecommendedQuantities() {
    container.querySelectorAll('#forecast-tbody tr[data-product-id]').forEach(row => {
      const recommendedCell = row.children[4]; // 推奨発注数量のセル
      const recommendedQuantity = recommendedCell?.textContent || '0';
      const quantityInput = row.querySelector('.order-quantity-input');

      if (quantityInput) {
        quantityInput.value = recommendedQuantity;
        quantityInput.dispatchEvent(new Event('input'));
      }
    });
  }

  // イベントハンドラの設定
  const searchButton = container.querySelector('#search-forecast-btn');
  if (searchButton) {
    searchButton.addEventListener('click', searchForecastData);
  }

  const executeButton = container.querySelector('#execute-order-btn');
  if (executeButton) {
    executeButton.addEventListener('click', executeOrder);
  }

  const recommendedButton = container.querySelector('#set-recommended-btn');
  if (recommendedButton) {
    recommendedButton.addEventListener('click', setRecommendedQuantities);
  }

  // 初期化
  loadInitialData();
}
